// OI skew meter (Skew + Direction H1). Two halves:
//  - parity: site/shared/oi-skew.js classifies the same inputs to the same
//    state as the REAL bot (_decide_core) and reproduces the REAL collector
//    reading, per tests/fixtures/oi_skew_parity.json generated by
//    tests/oi_skew_meter_parity.py (which CI also checks is current);
//  - display: live/stale/closed/missing/no-data/not-published handling, the
//    renderer's DOM output, and the page wiring/hash pins.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const {
  OI_SKEW_DEFAULTS, classifyOiSkewSignal, describeReferenceOiSkew, describeBotOiSkew, oiSkewMeterPercent,
} = require('../site/shared/oi-skew.js');

const root = path.join(__dirname, '..');
const fixture = JSON.parse(fs.readFileSync(path.join(root, 'tests', 'fixtures', 'oi_skew_parity.json'), 'utf8'));
let checks = 0;

// ── parity with the bot and the collector ─────────────────────────────────────
assert.equal(fixture.schema, 'oi_skew_meter_parity.v1');
assert.ok(fixture.cases.length >= 12);
const seen = new Set();
for (const c of fixture.cases) {
  const got = classifyOiSkewSignal(c.bot, c.params);
  assert.equal(got.state, c.bot.state, `${c.name}: meter ${got.state} vs bot ${c.bot.state} (${c.bot.reason})`);
  // Same delta arithmetic, bit for bit, as the bot's metadata.
  assert.equal(got.delta, c.bot.delta_from_session_start, `${c.name}: delta`);
  seen.add(got.state);
  // The collector's reference reading and the meter's raw value agree.
  const payload = {
    symbol: 'QQQ', timestamp: '2026-11-13T17:30:00+00:00',
    market_readings: [{ reading_id: 'reference_oi_skew', symbol: 'QQQ', values: c.reference.values,
      status: c.reference.status, calculation: { parameters: c.reference.parameters },
      input: { snapshot_timestamp: '2026-11-13T17:30:00+00:00' }, freshness: { status: 'live' } }],
  };
  const raw = describeReferenceOiSkew(payload, Date.parse('2026-11-13T17:30:30Z'));
  assert.equal(raw.value, c.reference.values.imbalance_ratio, `${c.name}: raw value`);
  checks += 3;
}
assert.deepEqual([...seen].sort(), ['bearish', 'bullish', 'neutral']);

// Named gates the operator sees, in the bot's order.
const byName = Object.fromEntries(fixture.cases.map(c => [c.name, c]));
const gate = n => classifyOiSkewSignal(byName[n].bot, byName[n].params).gate;
assert.equal(gate('missing_no_open_interest'), 'no_open_interest');
assert.equal(gate('neutral_thin_band'), 'insufficient_coverage');
assert.equal(gate('neutral_below_threshold'), 'below_threshold');
assert.equal(gate('boundary_session_change_float'), 'insufficient_session_change');
assert.equal(gate('boundary_exact_threshold_directional'), 'passed');
checks += 5;
assert.deepEqual({ ...OI_SKEW_DEFAULTS },
  { near_money_pct: 0.02, imbalance_threshold: 0.3, min_change_from_session_start: 0.1, min_band_strikes: 4 });
// No anchor is not a guessed anchor.
assert.equal(classifyOiSkewSignal({ imbalance_ratio: 0.9, band_strikes: 8 }).gate, 'insufficient_session_change');
checks += 2;

// ── reference reading display ─────────────────────────────────────────────────
const NOW = Date.parse('2026-11-13T17:35:00Z');
function live(overrides = {}, readingOverrides = {}) {
  return {
    symbol: 'QQQ', timestamp: '2026-11-13T17:33:59.190717+00:00',
    market_readings: [
      { reading_id: 'reference_pcr', values: { ratio: 1.2 } },
      { reading_id: 'reference_oi_skew', symbol: 'QQQ',
        input: { snapshot_timestamp: '2026-11-13T17:33:59.190717+00:00' },
        calculation: { version: 'reference_oi_skew.v1', parameters: { near_money_pct: 0.02 } },
        values: { near_money_call_oi: 59607, near_money_put_oi: 156520, imbalance_ratio: -0.44840764920625376, band_strikes: 27 },
        status: { code: 'ok', reason: null }, freshness: { status: 'live' }, ...readingOverrides },
    ],
    ...overrides,
  };
}
{
  const d = describeReferenceOiSkew(live(), NOW);
  assert.equal(d.availability, 'live');
  assert.equal(d.lean, 'put-heavy');
  assert.match(d.text, /-0\.448 \(put-heavy\)/);
  assert.match(d.detail, /59,607 call vs 156,520 put contracts over 27 strikes/);
  assert.match(d.detail, /not intraday flow or a win probability/);
  assert.equal(d.calc_version, 'reference_oi_skew.v1');
  checks += 6;
}
{ // stale: older than the 2-minute chain bound
  const d = describeReferenceOiSkew(live(), Date.parse('2026-11-13T17:40:00Z'));
  assert.equal(d.availability, 'stale'); checks++;
}
{ // stale: collector itself says not live
  const d = describeReferenceOiSkew(live({}, { freshness: { status: 'stale' } }), NOW);
  assert.equal(d.availability, 'stale'); checks++;
}
{ // closed: leftover from a prior session
  const d = describeReferenceOiSkew(live(), Date.parse('2026-11-14T14:00:00Z'));
  assert.equal(d.availability, 'closed'); checks++;
}
{ // missing reading / missing payload / wrong symbol
  assert.equal(describeReferenceOiSkew({ symbol: 'QQQ', market_readings: [] }, NOW).availability, 'unavailable');
  assert.equal(describeReferenceOiSkew(null, NOW).availability, 'unavailable');
  assert.equal(describeReferenceOiSkew(live({}, { symbol: 'SPY' }), NOW).availability, 'unavailable');
  checks += 3;
}
{ // no OI in band
  const d = describeReferenceOiSkew(live({}, { values: { imbalance_ratio: null, band_strikes: 0 },
    status: { code: 'no_data', reason: 'no_open_interest_in_reference_band' } }), NOW);
  assert.equal(d.availability, 'no_data');
  assert.equal(d.value, null);
  checks += 2;
}
{ // balanced / call-heavy wording
  assert.equal(describeReferenceOiSkew(live({}, { values: { imbalance_ratio: 0, band_strikes: 9 } }), NOW).lean, 'balanced');
  assert.equal(describeReferenceOiSkew(live({}, { values: { imbalance_ratio: 0.2, band_strikes: 9 } }), NOW).lean, 'call-heavy');
  checks += 2;
}

// ── bot state: never inferred without a projection ───────────────────────────
{
  const d = describeBotOiSkew(null, NOW);
  assert.equal(d.availability, 'not_published');
  assert.equal(d.state, 'unknown');
  assert.equal(describeBotOiSkew({ schema_version: 'other' }, NOW).availability, 'not_published');
  const p = { schema_version: 'oi_skew_meter.v1', account_alias: 'OI Skew', session_phase: 'open',
    observed_snapshot_timestamp: '2026-11-13T17:33:59Z', imbalance_ratio: -0.45,
    session_start_imbalance: -0.2, band_strikes: 27, params: { imbalance_threshold: 0.3 } };
  const b = describeBotOiSkew(p, NOW);
  assert.equal(b.state, 'bearish');
  assert.equal(b.availability, 'live');
  assert.equal(b.text, 'Bot signal: Bearish');
  assert.equal(describeBotOiSkew(p, Date.parse('2026-11-13T17:50:00Z')).text, 'Bot signal: Bearish (stale)');
  checks += 7;
}

// ── scale ─────────────────────────────────────────────────────────────────────
assert.equal(oiSkewMeterPercent(-1), 0);
assert.equal(oiSkewMeterPercent(0), 50);
assert.equal(oiSkewMeterPercent(1), 100);
assert.equal(oiSkewMeterPercent(3), 100);
assert.equal(oiSkewMeterPercent(null), null);
checks += 5;

// ── page wiring ───────────────────────────────────────────────────────────────
const html = fs.readFileSync(path.join(root, 'site', 'index.html'), 'utf8');
for (const rel of ['shared/oi-skew.js', 'js/oi-skew-meter.js']) {
  const src = fs.readFileSync(path.join(root, 'site', rel));
  const hash = createHash('sha256').update(src).digest('hex').slice(0, 16);
  assert.ok(html.includes(`${rel}?v=${hash}`), `${rel} script URL must match its content hash`);
  checks++;
}
assert.ok(html.includes('id="oi-skew-meter"'), 'meter section present');
assert.ok(/role="meter"/.test(html) && /aria-valuemin="-1"/.test(html) && /aria-valuemax="1"/.test(html),
  'meter exposes an accessible -1..1 range');
const fetchCycle = fs.readFileSync(path.join(root, 'site', 'js', 'data-fetch-cycle.js'), 'utf8');
assert.ok(fetchCycle.includes('updateOiSkewMeter(qqq.data)'), 'meter refreshes on the QQQ 60s cycle');
checks += 3;

// ── renderer against a minimal DOM shim ──────────────────────────────────────
{
  const els = {};
  const mk = id => (els[id] = { id, textContent: '', title: '', dataset: {}, style: {}, hidden: false,
    attrs: {}, setAttribute(k, v) { this.attrs[k] = String(v); } });
  for (const id of ['oi-skew-meter', 'oi-skew-marker', 'oi-skew-track', 'oi-skew-value', 'oi-skew-lean',
    'oi-skew-meta', 'oi-skew-bot', 'oi-skew-bot-detail', 'oi-skew-thresholds']) mk(id);
  const shared = require('../site/shared/oi-skew.js');
  const ctx = { document: { getElementById: id => els[id] || null }, ...shared, Date, Math, Number, Intl };
  const vm = require('node:vm');
  vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(path.join(root, 'site', 'js', 'oi-skew-meter.js'), 'utf8'), ctx);
  ctx.updateOiSkewMeter(live(), NOW);
  assert.equal(els['oi-skew-meter'].dataset.state, 'live');
  assert.equal(els['oi-skew-value'].textContent, '−0.448');
  assert.equal(els['oi-skew-lean'].textContent, 'Put-heavy');
  assert.equal(els['oi-skew-track'].attrs['aria-valuenow'], '-0.448');
  assert.match(els['oi-skew-track'].attrs['aria-valuetext'], /put-heavy/);
  assert.equal(els['oi-skew-marker'].style.left, `${oiSkewMeterPercent(-0.44840764920625376)}%`);
  assert.equal(els['oi-skew-bot'].textContent, 'Bot signal: not published');
  assert.match(els['oi-skew-meta'].textContent, /QQQ/);
  ctx.updateOiSkewMeter({ symbol: 'QQQ', market_readings: [] }, NOW);
  assert.equal(els['oi-skew-meter'].dataset.state, 'unavailable');
  assert.equal(els['oi-skew-marker'].hidden, true);
  assert.equal(els['oi-skew-value'].textContent, '—');
  checks += 11;
}

// ── freshness regressions (Chej review of 074639e) ───────────────────────────
// A good snapshot followed by failed/empty refreshes, and elapsed time with
// no refresh at all, must never leave the meter labelled live.
{
  assert.ok(fetchCycle.includes('noteOiSkewRefreshFailure(chainState.QQQ.error)'),
    'failed/empty QQQ refresh path notifies the meter');
  const { degradeOiSkewForRefreshFailure } = require('../site/shared/oi-skew.js');
  const ok = describeReferenceOiSkew(live(), NOW);
  assert.equal(degradeOiSkewForRefreshFailure(ok, null), ok);
  const d = degradeOiSkewForRefreshFailure(ok, 'HTTP 503');
  assert.equal(d.availability, 'stale');
  assert.match(d.detail, /Latest refresh failed \(HTTP 503\)/);
  assert.equal(degradeOiSkewForRefreshFailure({ ...ok, availability: 'closed' }, 'x').availability, 'closed');
  checks += 5;

  const els = {};
  const mk = id => (els[id] = { id, textContent: '', title: '', dataset: {}, style: {}, hidden: false,
    attrs: {}, setAttribute(k, v) { this.attrs[k] = String(v); } });
  for (const id of ['oi-skew-meter', 'oi-skew-marker', 'oi-skew-track', 'oi-skew-value', 'oi-skew-lean',
    'oi-skew-meta', 'oi-skew-bot', 'oi-skew-bot-detail', 'oi-skew-thresholds']) mk(id);
  let clock = NOW;
  const timers = [];
  const FakeDate = class extends Date { static now() { return clock; } };
  const shared = require('../site/shared/oi-skew.js');
  const ctx = { document: { getElementById: id => els[id] || null }, ...shared, Date: FakeDate, Math, Number, Intl,
    String, setInterval: (fn, ms) => { timers.push({ fn, ms }); return timers.length; } };
  const vm = require('node:vm');
  vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(path.join(root, 'site', 'js', 'oi-skew-meter.js'), 'utf8'), ctx);
  const tick = () => timers.forEach(t => t.fn());
  const state = () => els['oi-skew-meter'].dataset.state;

  // good initial snapshot
  ctx.updateOiSkewMeter(live(), clock);
  assert.equal(state(), 'live');
  assert.equal(timers.length, 1, 'one age ticker');
  assert.ok(timers[0].ms <= 30000, 'ticker re-evaluates age well inside the 2-minute stale bound');
  // failed refresh 10 s later: last good value stays visible but is not live
  clock += 10000;
  ctx.noteOiSkewRefreshFailure(`QQQ snapshot could not be loaded.`, clock);
  assert.equal(state(), 'stale');
  assert.equal(els['oi-skew-value'].textContent, '−0.448', 'last good value kept on screen');
  assert.match(els['oi-skew-meta'].textContent, /stale · refresh failed/);
  assert.match(els['oi-skew-meter'].title, /Latest refresh failed/);
  assert.match(els['oi-skew-track'].attrs['aria-valuetext'], /stale/);
  // a successful refresh clears the failure
  ctx.updateOiSkewMeter(live(), clock);
  assert.equal(state(), 'live');
  assert.doesNotMatch(els['oi-skew-meta'].textContent, /refresh failed/);
  // empty refresh (no rows) is a failure too
  ctx.noteOiSkewRefreshFailure('No QQQ rows in the latest snapshot.', clock);
  assert.equal(state(), 'stale');
  // failure with no prior good snapshot: unavailable, never live
  ctx.updateOiSkewMeter(null, clock);
  ctx.noteOiSkewRefreshFailure('HTTP 500', clock);
  assert.equal(state(), 'unavailable');
  assert.equal(timers.length, 1, 'no duplicate tickers');
  checks += 13;

  // elapsed freshness with NO further calls from the fetch cycle
  clock = NOW;
  ctx.updateOiSkewMeter(live(), clock);
  assert.equal(state(), 'live');
  clock = Date.parse('2026-11-13T17:36:30Z'); tick();          // 2.5 min after the snapshot
  assert.equal(state(), 'stale');
  clock = Date.parse('2026-11-13T21:40:00Z'); tick();          // > 4 h later
  assert.equal(state(), 'closed');
  assert.match(els['oi-skew-meta'].textContent, /session closed/);
  checks += 4;
}

console.log(`oi_skew_meter: ${checks} checks passed (${fixture.cases.length} parity cases)`);
